package com.praveen.order.model; import jakarta.persistence.*; import java.math.BigDecimal;
@Entity @Table(name="orders") public class Order { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private Long productId; private Integer quantity; private BigDecimal total; @Enumerated(EnumType.STRING) private Status status=Status.CREATED; public enum Status{CREATED,CONFIRMED,CANCELLED} public Long getId(){return id;} public Long getProductId(){return productId;} public void setProductId(Long v){productId=v;} public Integer getQuantity(){return quantity;} public void setQuantity(Integer v){quantity=v;} public BigDecimal getTotal(){return total;} public void setTotal(BigDecimal v){total=v;} public Status getStatus(){return status;} public void setStatus(Status v){status=v;} }
